<?php
namespace Tests\Feature;
use App\Models\{BookingServis,JenisServis,Servis,User}; use App\Services\{BookingServisService,ServisService}; use Illuminate\Foundation\Testing\DatabaseTransactions; use Illuminate\Support\Facades\Schema; use RuntimeException; use Tests\TestCase;
class ServisStage5ATest extends TestCase {
 use DatabaseTransactions;
 private function user(string $role):User{return User::whereHas('role',fn($q)=>$q->where('nama_role',$role))->firstOrFail();}
 private function booking(User $u,string $status='diterima'):BookingServis{$v=$u->pelanggan->kendaraan()->create(['merk'=>'QA','model'=>'WO','nomor_polisi'=>'WO-'.random_int(1000,9999),'kilometer'=>10000,'status'=>'aktif']);$t=JenisServis::where('status','aktif')->firstOrFail();$b=app(BookingServisService::class)->create($u->pelanggan->id_pelanggan,$v->id_kendaraan_pelanggan,$t->id_jenis_servis,now()->addDay()->toDateString(),'10:00','Keluhan','Catatan');$b->forceFill(['status'=>$status])->save();return $b;}
 public function test_baseline_tables_are_imported():void{$this->assertSame(2,Servis::count());$this->assertDatabaseCount('detail_servis',1);$this->assertDatabaseHas('servis',['id_servis'=>1,'kode_servis'=>'SRV-202609-70A40DC2']);}
 public function test_work_order_creation_locks_and_syncs_booking():void{$b=$this->booking($this->user('pelanggan'));$s=app(ServisService::class)->createFromBooking($b->id_booking_servis,$this->user('petugas')->petugas->id_petugas,12000,'Masuk');$this->assertSame('pemeriksaan',$s->status);$this->assertSame('diproses',$b->fresh()->status);$this->assertSame(12000,$b->kendaraan->fresh()->kilometer);}
 public function test_duplicate_work_order_is_blocked():void{$b=$this->booking($this->user('pelanggan'));$svc=app(ServisService::class);$svc->createFromBooking($b->id_booking_servis,$this->user('petugas')->petugas->id_petugas,null,null);$this->expectException(RuntimeException::class);$svc->createFromBooking($b->id_booking_servis,$this->user('petugas')->petugas->id_petugas,null,null);}
 public function test_status_and_kilometer_rules_are_enforced():void{$b=$this->booking($this->user('pelanggan'),'menunggu');$this->expectException(RuntimeException::class);app(ServisService::class)->createFromBooking($b->id_booking_servis,$this->user('petugas')->petugas->id_petugas,9000,null);}
 public function test_invalid_petugas_rolls_back_booking_and_service():void{$b=$this->booking($this->user('pelanggan'));$this->expectException(\Illuminate\Database\QueryException::class);try{app(ServisService::class)->createFromBooking($b->id_booking_servis,999999,11000,null);}finally{$this->assertSame('diterima',$b->fresh()->status);$this->assertDatabaseMissing('servis',['id_booking_servis'=>$b->id_booking_servis]);}}
 public function test_inspection_and_detail_workflow():void{$b=$this->booking($this->user('pelanggan'));$s=app(ServisService::class)->createFromBooking($b->id_booking_servis,$this->user('petugas')->petugas->id_petugas,null,null);app(ServisService::class)->updateInspection($s->id_servis,'Perlu pemeriksaan rem','Teknis');app(ServisService::class)->addDetail($s->id_servis,null,'Pemeriksaan rem','125000','QA');$this->assertDatabaseHas('servis',['id_servis'=>$s->id_servis,'status'=>'dikerjakan','hasil_pemeriksaan'=>'Perlu pemeriksaan rem']);$this->assertDatabaseHas('detail_servis',['id_servis'=>$s->id_servis,'deskripsi_pekerjaan'=>'Pemeriksaan rem','biaya'=>'125000.00']);}
 public function test_detail_cannot_be_added_before_inspection_or_after_transaction_boundary():void{$b=$this->booking($this->user('pelanggan'));$s=app(ServisService::class)->createFromBooking($b->id_booking_servis,$this->user('petugas')->petugas->id_petugas,null,null);$this->expectException(RuntimeException::class);app(ServisService::class)->addDetail($s->id_servis,null,'Jasa','1',null);}
 public function test_customer_can_only_view_own_service():void{$a=$this->user('pelanggan');$b=$this->booking($a);$s=app(ServisService::class)->createFromBooking($b->id_booking_servis,$this->user('petugas')->petugas->id_petugas,null,null);$this->actingAs($a)->get('/pelanggan/servis/'.$s->id_servis)->assertOk();$other=User::whereHas('role',fn($q)=>$q->where('nama_role','pelanggan'))->where('id_user','<>',$a->id_user)->first();if($other){$this->actingAs($other)->get('/pelanggan/servis/'.$s->id_servis)->assertForbidden();}}
 public function test_roles_and_customer_mutation_boundary():void{$this->get('/pelanggan/servis')->assertRedirect('/login');$this->actingAs($this->user('pelanggan'))->get('/admin/servis')->assertForbidden();$this->actingAs($this->user('admin'))->get('/admin/servis')->assertOk();$this->actingAs($this->user('petugas'))->get('/petugas/servis')->assertOk();}
 public function test_stage_does_not_create_transactions_or_sparepart_changes():void{$this->assertTrue(Schema::hasTable('servis_sparepart'));$this->assertTrue(Schema::hasTable('transaksi'));$this->assertTrue(Schema::hasTable('pembayaran'));}
}
